using System.Collections.Generic;
using UnityEngine;

namespace Parasite.Characters
{
    /// <summary>
    /// Runtime list of the skinned character variants (generated by Tools/blender/characters and
    /// Editor/CharacterModelImporter.RebuildBatch). Loaded from Resources/Characters/CharacterCatalog.
    /// </summary>
    public class CharacterCatalog : ScriptableObject
    {
        public const string Resource = "Characters/CharacterCatalog";

        [System.Serializable]
        public class Entry
        {
            public string id;
            public Profession profession;
            /// <summary>Display names (HostCharacter.DisplayName / story actors) that map onto this exact variant.</summary>
            public string[] names = new string[0];
            /// <summary>Story character: never picked for anonymous NPCs.</summary>
            public bool unique;
            public float gender;
            public float height = 1.75f;
            public GameObject prefab;
            /// <summary>Default garment tints (linear multipliers) for the cloth atlas tint groups A/B/C.</summary>
            public Color tintA = Color.white, tintB = Color.white, tintC = Color.white;
            public bool hasTintA, hasTintB, hasTintC;
            /// <summary>Palette names used to re-tint anonymous instances (see CharacterPalettes).</summary>
            public string paletteA = "", paletteB = "", paletteC = "";
            public int[] lodTriangles = new int[0];
        }

        public List<Entry> entries = new();

        static CharacterCatalog cached;
        static bool loaded;

        public static CharacterCatalog Load()
        {
            if (!loaded)
            {
                cached = Resources.Load<CharacterCatalog>(Resource);
                loaded = true;
            }
            return cached;
        }

        public Entry FindByName(string displayName)
        {
            if (string.IsNullOrEmpty(displayName)) return null;
            foreach (var e in entries)
                if (e != null && e.prefab && e.names != null)
                    foreach (var n in e.names)
                        if (string.Equals(n, displayName, System.StringComparison.OrdinalIgnoreCase)) return e;
            return null;
        }

        public Entry FindById(string id)
        {
            foreach (var e in entries) if (e != null && e.prefab && e.id == id) return e;
            return null;
        }

        /// <summary>
        /// Deterministic pick for an anonymous NPC: prefers variants of the profession that no named character uses
        /// (so extras do not clone Maya or Sgt. Reed), then any non-unique variant of the profession.
        /// </summary>
        public Entry Pick(Profession profession, int seed)
        {
            var pool = new List<Entry>();
            foreach (var e in entries)
                if (e != null && e.prefab && !e.unique && e.profession == profession && (e.names == null || e.names.Length == 0)) pool.Add(e);
            if (pool.Count == 0) foreach (var e in entries) if (e != null && e.prefab && !e.unique && e.profession == profession) pool.Add(e);
            if (pool.Count == 0) foreach (var e in entries) if (e != null && e.prefab && !e.unique) pool.Add(e);
            if (pool.Count == 0) return null;
            uint h = (uint)seed * 2654435761u ^ (uint)profession * 40503u;
            h ^= h >> 15;
            return pool[(int)(h % (uint)pool.Count)];
        }
    }
}
